delete from expertruleaction;
delete from expertruletestcondition;
delete from expertrulecondition;
delete from expertrule;
delete from expertrulespecimentype;
delete from organismcoding where id >= 100000 and id < 200000;
delete from listitem where listid = 77 and id > 2000 and id < 10000;

delete from listitem where id >= 2076 and id <= 2080;
delete from listitem where id >= 1264 and id <= 1268;


SELECT setval(
  pg_get_serial_sequence('organismcoding', 'id'),
  COALESCE(MAX(id), 0) + 1,
  false
)
FROM organismcoding;







